#include <bits/stdc++.h>
using namespace std;

#define N 200010
#define INF (long long)2e+18

using namespace std;

int main(void) {
	int n, m;
	long long h[N];
	vector<pair<int, long long> >e[N];

	priority_queue<pair<long long, int> >pq;
	pair<long long, int> p;
	long long d[N];

	int k, x, y;
	long long ans;

	cin >> n >> m;
	for (int i = 0; i < n; i++)cin >> h[i];
	for (int i = 0; i < m; i++) {
		cin >> x >> y;
		x--;
		y--;
		e[x].push_back({ y,max(h[y] - h[x],(long long)0) });
		e[y].push_back({ x,max(h[x] - h[y],(long long)0) });
	}

	for (int i = 0; i < n; i++)d[i] = INF;
	d[0] = 0;
	ans = 0;
	pq.push({ -d[0],0 });

	for (int i = 0; i < n; i++) {
			p = pq.top();
		while (d[p.second] < -p.first) {
				pq.pop();
				p = pq.top();
		}
		pq.pop();
		k = p.second;
		ans = max(ans, h[0] - h[k] - d[k]);
		for (int i = 0; i < e[k].size(); i++) {
			if (d[e[k][i].first] > (d[k] + e[k][i].second)) {
				d[e[k][i].first] = d[k] + e[k][i].second;
				pq.push({ -d[e[k][i].first],e[k][i].first });
			}
		}
	}

	cout << ans << endl;
	return 0;
}
